package com.bank.joincost.cost;

// Models the cost of a single indexed lookup as "disk reads = B-tree depth".
public class IndexCostModel {
    private final int treeDepth; // levels in the B-tree, each a potential disk read

    public IndexCostModel(int treeDepth) { this.treeDepth = treeDepth; }

    // Disk reads for matching 'matches' rows via the index.
    public long diskReadsFor(long matches) {
        return matches * treeDepth;
    }
}
