package com.bank.joincost.cost;

import java.util.logging.Logger;

// Estimates scatter-gather plus intermediate-row cost of a JOIN.
public class JoinCostSimulator {
    private static final Logger log = Logger.getLogger(JoinCostSimulator.class.getName());
    private final int shardCount;
    private final IndexCostModel indexModel;

    public JoinCostSimulator(int shardCount, IndexCostModel indexModel) {
        this.shardCount = shardCount;
        this.indexModel = indexModel;
    }

    // shardLocal=true means the shard key is in the filter, so only ONE shard is touched.
    public long estimate(boolean shardLocal, long matchedRows, long intermediateRows) {
        int shardsTouched = shardLocal ? 1 : shardCount;
        long diskReads = indexModel.diskReadsFor(matchedRows);
        long networkRows = shardLocal ? 0 : intermediateRows; // cross-shard ships intermediates
        long total = (long) shardsTouched * 50L + diskReads + networkRows;
        log.info(() -> "JOIN cost: shardsTouched=" + shardsTouched
                + " diskReads=" + diskReads + " networkRows=" + networkRows
                + " totalUnits=" + total);
        return total;
    }
}
