package com.bank.joincost.service;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Demonstrates why per-user JOIN results cannot be cached effectively.
public class PersonalizedDashboardService {
    private static final Logger log = Logger.getLogger(PersonalizedDashboardService.class.getName());
    private final Map<String, String> cache = new HashMap<>();
    private long hits = 0, misses = 0;

    public String dashboardFor(String customerId) {
        if (cache.containsKey(customerId)) { hits++; return cache.get(customerId); }
        misses++;
        String built = "DASHBOARD(" + customerId + ")"; // pretend this ran the 3-table JOIN
        cache.put(customerId, built);
        log.warning(() -> "Cache MISS for " + customerId + " — personalized JOIN re-run");
        return built;
    }

    public String stats() { return "hits=" + hits + " misses=" + misses; }
}
