package com.bank.joincost;

import com.bank.joincost.cost.*;
import com.bank.joincost.service.PersonalizedDashboardService;
import java.util.logging.*;

public class JoinCostDemo {
    private static final Logger log = Logger.getLogger(JoinCostDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        IndexCostModel idx = new IndexCostModel(4);      // 4-level B-tree
        JoinCostSimulator sim = new JoinCostSimulator(200, idx);

        log.info("Query A: Rajesh's dashboard (shard-local, filter includes customer_id)");
        sim.estimate(true, 500, 500);                    // one shard, small result

        log.info("Query B: analytics JOIN on amount>1,00,000 (cross-shard, no customer_id)");
        sim.estimate(false, 1_000_000, 10_000_000);      // all shards, huge intermediates

        PersonalizedDashboardService dash = new PersonalizedDashboardService();
        for (String c : new String[]{"CUST-RAJESH","CUST-PRIYA","CUST-OTHER"}) dash.dashboardFor(c);
        log.info("Dashboard cache " + dash.stats());
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }
}

